// Verify the HMAC-SHA256 signature Convex put on the request.
// Signed string: "<timestamp>.<raw body>" (see convex/lib/signing.ts).
const crypto = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment');
}

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'];

// rawBody: true puts the untouched bytes in binary.data; fall back to re-serialising.
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

let reason = null;
if (!timestamp || !signature) {
  reason = 'missing signature headers';
} else if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) {
  reason = 'timestamp outside 5 minute window';
} else {
  const expected = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
  const a = Buffer.from(String(signature));
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    reason = 'signature mismatch';
  }
}

let payload = null;
if (!reason) {
  try {
    payload = JSON.parse(raw);
  } catch (e) {
    reason = 'body is not valid JSON';
  }
}

return [{ json: { valid: reason === null, reason, payload } }];

// Turn the event into one human message. Only the fields in the payload are
// used; no lookups against other systems.
const p = $input.first().json.payload;

const templates = {
  request_created: {
    subject: `New borrow request for your ${p.toolName}`,
    text: `${p.counterpartName} would like to borrow your ${p.toolName} from ${p.startDate} to ${p.endDate}. Open LendLoop > Incoming to approve or decline.`,
  },
  request_approved: {
    subject: `Your request for ${p.toolName} was approved`,
    text: `${p.counterpartName} approved your request for ${p.toolName} (${p.startDate} to ${p.endDate}). Please return it by ${p.endDate}.`,
  },
  request_declined: {
    subject: `Your request for ${p.toolName} was declined`,
    text: `${p.counterpartName} could not lend ${p.toolName} this time. The board has other options.`,
  },
  request_cancelled: {
    subject: `Request for ${p.toolName} cancelled`,
    text: `${p.counterpartName} cancelled the request for your ${p.toolName} (${p.startDate} to ${p.endDate}).`,
  },
  loan_returned: {
    subject: `${p.toolName} marked as returned`,
    text: `${p.counterpartName} confirmed ${p.toolName} is back. Thanks for returning it!`,
  },
};

const t = templates[p.event] || {
  subject: `LendLoop update for ${p.toolName}`,
  text: `The request for ${p.toolName} is now "${p.status}".`,
};

return [{
  json: {
    event: p.event,
    loanId: p.loanId,
    idempotencyKey: p.idempotencyKey,
    to: p.recipient.email,
    toName: p.recipient.name,
    subject: t.subject,
    text: `Hi ${p.recipient.name},\n\n${t.text}\n\n- LendLoop`,
    channel: $env.LENDLOOP_NOTIFY_VIA === 'email' ? 'email' : 'mock',
  },
}];

// Mock channel: the "notification" is the execution log itself.
// Visible under Executions in n8n, which is enough for a review setup.
const m = $input.first().json;
console.log(`[LendLoop mock notification] to=${m.to} subject="${m.subject}" key=${m.idempotencyKey}`);
return [{ json: { delivered: 'mock', to: m.to, subject: m.subject, text: m.text, idempotencyKey: m.idempotencyKey } }];
